<body><main class="shell" aria-labelledby="identity-title"><section class="brand" aria-label="<?= $escape($brandName) ?> 品牌信息"><div><div class="mark" aria-hidden="true"><?= $escape($brandMark) ?></div><h1><?= $escape($brandHeadline) ?></h1><p><?= $escape($brandDescription) ?></p></div><div class="trust"><i aria-hidden="true"></i>由安全的 Identity 服务保护</div></section><section class="panel"><div class="eyebrow">Secure identity</div><h2 id="identity-title"><?= $mode === 'consent' ? '确认授权' : '欢迎回来' ?></h2><p class="subtitle"><?= $mode === 'consent' ? $escape($applicationName) . ' 请求访问以下信息。' : '使用你的企业凭证继续访问应用。' ?></p><?php if ($error !== ''): ?><div class="error" role="alert"><?= $escape($error) ?></div><?php endif; ?><?php if ($mode === 'login'): ?><form method="post" action="/identity/interaction/login"><input type="hidden" name="csrf_token" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="transaction_id" value="<?= $escape($transactionId) ?>"><div class="field"><label for="username">用户名</label><input id="username" name="username" autocomplete="username" required autofocus></div><div class="field"><label for="password">密码</label><input id="password" type="password" name="password" autocomplete="current-password" required></div><div class="field"><label for="captcha">验证码</label><div class="captcha-row"><input id="captcha" name="captcha" inputmode="text" required aria-describedby="captcha-help"><a href="/identity/interaction?transaction_id=<?= $escape($transactionId) ?>" aria-label="刷新验证码"><img src="/identity/captcha" alt="验证码"></a></div><small id="captcha-help">看不清可点击图片刷新</small></div><button class="primary" type="submit">安全登录</button></form><?php else: ?><form method="post" action="/identity/interaction/consent"><input type="hidden" name="csrf_token" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="transaction_id" value="<?= $escape($transactionId) ?>"><div class="consent-card" aria-label="请求的权限"><?php foreach ($scopes as $scope): ?><div class="scope <?= $scope['name'] === 'offline_access' ? 'offline_access' : '' ?>"><span aria-hidden="true">✓</span><div><b><?= $escape($scope['label']) ?></b><small><?= $escape($scope['description']) ?></small></div></div><?php endforeach; ?></div><div class="actions"><button class="secondary" name="approved" value="0">拒绝</button><button class="primary" name="approved" value="1">允许并继续</button></div></form><?php endif; ?><div class="foot">不会向应用披露你的密码</div></section></main></body></html>
